// Pure-JS AES block cipher (FIPS-197), byte-oriented implementation.
// Mirrors the observable behavior of pyaes.AESBlockModeOfOperation's cipher:
// supports 16/24/32-byte keys; any other size raises "Invalid key size".

import { SBOX, INV_SBOX, RCON } from './aes-tables.mjs';

// GF(2^8) multiplication by x (i.e. 0x02), reducing modulo the AES polynomial.
function xtime(a) {
  a <<= 1;
  if (a & 0x100) a ^= 0x11b;
  return a & 0xff;
}

// GF(2^8) multiplication of two bytes.
function gmul(a, b) {
  let p = 0;
  while (b > 0) {
    if (b & 1) p ^= a;
    a = xtime(a);
    b >>= 1;
  }
  return p;
}

export class AESCipher {
  constructor(key) {
    const nk = key.length / 4; // words in the key
    if (nk !== 4 && nk !== 6 && nk !== 8) {
      throw new Error('Invalid key size');
    }
    this.nk = nk;
    this.nr = nk + 6; // number of rounds
    this.roundKeys = this._expandKey(key);
  }

  // Key expansion -> flat Uint8Array of 16 * (nr + 1) bytes, column-major words.
  _expandKey(key) {
    const { nk, nr } = this;
    const totalWords = 4 * (nr + 1);
    const w = new Uint8Array(totalWords * 4);
    w.set(key);
    for (let i = nk; i < totalWords; i++) {
      let t0 = w[(i - 1) * 4], t1 = w[(i - 1) * 4 + 1],
          t2 = w[(i - 1) * 4 + 2], t3 = w[(i - 1) * 4 + 3];
      if (i % nk === 0) {
        // RotWord + SubWord + Rcon
        const r = RCON[i / nk];
        const n0 = SBOX[t1] ^ r, n1 = SBOX[t2], n2 = SBOX[t3], n3 = SBOX[t0];
        t0 = n0; t1 = n1; t2 = n2; t3 = n3;
      } else if (nk > 6 && i % nk === 4) {
        t0 = SBOX[t0]; t1 = SBOX[t1]; t2 = SBOX[t2]; t3 = SBOX[t3];
      }
      const prev = (i - nk) * 4;
      w[i * 4] = w[prev] ^ t0;
      w[i * 4 + 1] = w[prev + 1] ^ t1;
      w[i * 4 + 2] = w[prev + 2] ^ t2;
      w[i * 4 + 3] = w[prev + 3] ^ t3;
    }
    return w;
  }

  _addRoundKey(state, round) {
    const off = round * 16;
    for (let i = 0; i < 16; i++) state[i] ^= this.roundKeys[off + i];
  }

  // Encrypt a single 16-byte block (Uint8Array) -> Uint8Array(16).
  encryptBlock(block) {
    const s = Uint8Array.from(block); // state, column-major: s[r + 4*c] = block[r + 4*c]
    this._addRoundKey(s, 0);
    for (let round = 1; round <= this.nr; round++) {
      // SubBytes
      for (let i = 0; i < 16; i++) s[i] = SBOX[s[i]];
      // ShiftRows (row r shifted left by r, across columns)
      let t;
      t = s[1]; s[1] = s[5]; s[5] = s[9]; s[9] = s[13]; s[13] = t;                 // row 1
      t = s[2]; s[2] = s[10]; s[10] = t; t = s[6]; s[6] = s[14]; s[14] = t;       // row 2
