      // row 3: left shift by 3 == right shift by 1
      s = row3ShiftEncrypt(s);
      // MixColumns (skipped in the final round)
      if (round !== this.nr) {
        for (let c = 0; c < 4; c++) {
          const i = c * 4;
          const a0 = s[i], a1 = s[i + 1], a2 = s[i + 2], a3 = s[i + 3];
          s[i]     = gmul(a0, 2) ^ gmul(a1, 3) ^ a2 ^ a3;
          s[i + 1] = a0 ^ gmul(a1, 2) ^ gmul(a2, 3) ^ a3;
          s[i + 2] = a0 ^ a1 ^ gmul(a2, 2) ^ gmul(a3, 3);
          s[i + 3] = gmul(a0, 3) ^ a1 ^ a2 ^ gmul(a3, 2);
        }
      }
      this._addRoundKey(s, round);
    }
    return s;
  }

  // Decrypt a single 16-byte block (Uint8Array) -> Uint8Array(16).
  decryptBlock(block) {
    let s = Uint8Array.from(block);
    this._addRoundKey(s, this.nr);
