      t = s[2]; s[2] = s[10]; s[10] = t; t = s[6]; s[6] = s[14]; s[14] = t;       // row 2
      t = s[3]; s[3] = s[7]; s[7] = s[11]; s[11] = s[15]; s[15] = t;              // row 3 (right by 3)
      // InvSubBytes
      for (let i = 0; i < 16; i++) s[i] = INV_SBOX[s[i]];
      this._addRoundKey(s, round);
      // InvMixColumns (skipped after round 0 key addition)
      if (round !== 0) {
        for (let c = 0; c < 4; c++) {
          const i = c * 4;
