  _addRoundKey(state, round) {
    const off = round * 16;
    for (let i = 0; i < 16; i++) state[i] ^= this.roundKeys[off + i];
  }

  // Encrypt a single 16-byte block (Uint8Array) -> Uint8Array(16).
  // State layout is column-major: s[r + 4*c] = block[r + 4*c] (identity here).
  encryptBlock(block) {
    const s = Uint8Array.from(block);
    this._addRoundKey(s, 0);
    for (let round = 1; round <= this.nr; round++) {
      for (let i = 0; i < 16; i++) s[i] = SBOX[s[i]]; // SubBytes
      shiftRows(s);
      if (round !== this.nr) mixColumns(s);
      this._addRoundKey(s, round);
    }
    return s;
  }

  // Decrypt a single 16-byte block (Uint8Array) -> Uint8Array(16).
  decryptBlock(block) {
    const s = Uint8Array.from(block);
    this._addRoundKey(s, this.nr);
    for (let round = this.nr - 1; round >= 0; round--) {
      invShiftRows(s);
      for (let i = 0; i < 16; i++) s[i] = INV_SBOX[s[i]]; // InvSubBytes
      this._addRoundKey(s, round);
      if (round !== 0) invMixColumns(s);
    }
    return s;
  }
}

