// ECB mode of operation on top of the raw AES block cipher.
// Mirrors pyaes.AESModeOfOperationECB observable behavior:
// encrypt()/decrypt() accept exactly one 16-byte block.

import { AESCipher } from './aes-core.mjs';

export class AESModeOfOperationECB {
  constructor(key) {
    this._cipher = new AESCipher(key);
  }

  encrypt(plaintext) {
    if (plaintext.length !== 16) {
      throw new Error('plaintext block must be 16 bytes');
    }
    return this._cipher.encryptBlock(plaintext);
  }

  decrypt(ciphertext) {
    if (ciphertext.length !== 16) {
      throw new Error('ciphertext block must be 16 bytes');
    }
    return this._cipher.decryptBlock(ciphertext);
  }
}

