// Reproduces CPython's repr() of a bytes object, which is what
// print(bytes) emits. Rules:
//  - quoted with ' ... ' unless the data contains ' but not " (then " ... ")
//  - the active quote char and backslash are backslash-escaped
//  - \t, \n, \r get their short escapes
//  - other printable ASCII (0x20..0x7e) is emitted literally
//  - everything else becomes \xhh (lowercase hex)

export function pythonBytesRepr(bytes) {
  let hasSingle = false, hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;       // '
    else if (b === 0x22) hasDouble = true;  // "
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === quoteCode || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += '\\x' + b.toString(16).padStart(2, '0');
    }
  }
  out += quote;
  return out;
}

