// Minimal argparse-compatible parser for this script's interface:
// three required string options --key1, --key2, --data. Matches Python
// argparse behavior for the cases this program can hit:
//  - "--opt value" and "--opt=value" forms
//  - unknown options -> usage + error on stderr, exit code 2
//  - missing required options -> usage + error on stderr, exit code 2
//  - -h/--help -> usage on stdout, exit code 0

const OPTIONS = ['key1', 'key2', 'data'];

function prog() {
  // argparse uses os.path.basename(sys.argv[0]); for us that's the script name.
  const script = process.argv[1] || 'test15.mjs';
  return script.slice(script.lastIndexOf('/') + 1);
}

function usage() {
  return `usage: ${prog()} [-h] --key1 KEY1 --key2 KEY2 --data DATA`;
}

function fail(message) {
  process.stderr.write(usage() + '\n');
  process.stderr.write(`${prog()}: error: ${message}\n`);
  process.exit(2);
}

export function parseArgs() {
  const values = {};
  const argv = process.argv.slice(2);

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      process.stdout.write(usage() + '\n');
      process.exit(0);
    }

    let name = null, inlineValue = null;
    if (arg.startsWith('--')) {
      const eq = arg.indexOf('=');
      if (eq !== -1) {
        name = arg.slice(2, eq);
        inlineValue = arg.slice(eq + 1);
      } else {
        name = arg.slice(2);
      }
    }

    if (name === null || !OPTIONS.includes(name)) {
      fail(`unrecognized arguments: ${arg}`);
    }

    if (inlineValue !== null) {
      values[name] = inlineValue;
    } else {
      if (i + 1 >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      values[name] = argv[++i];
    }
  }

  const missing = OPTIONS.filter((o) => !(o in values));
  if (missing.length > 0) {
    fail(`the following arguments are required: ${missing.map((o) => '--' + o).join(', ')}`);
  }

  return values;
}

