import { pythonBytesRepr } from './lib/pybytes.mjs';

function main() {
  const args = parseArgs();

  // Encrypt with first key, decrypt with second key
  const aes1 = new AESModeOfOperationECB(Buffer.from(args.key1, 'utf8'));
  const aes2 = new AESModeOfOperationECB(Buffer.from(args.key2, 'utf8'));
  const ciphertext = aes1.encrypt(Buffer.from(args.data, 'utf8'));
  const wrongPlaintext = aes2.decrypt(ciphertext);
  console.log(pythonBytesRepr(ciphertext));
  console.log(pythonBytesRepr(wrongPlaintext));
}

main();

